<style>
    :root{--asrama-navy:#183a5a;--asrama-teal:#168b87;--asrama-soft:#edf7f6;--asrama-ink:#1d2b3a}
    .asrama-hero{display:flex;justify-content:space-between;align-items:center;gap:1.5rem;padding:1.6rem 1.75rem;margin-bottom:1.35rem;border-radius:24px;color:#fff;background:linear-gradient(135deg,var(--asrama-navy),var(--asrama-teal));box-shadow:0 18px 42px rgba(24,58,90,.18)}
    .asrama-hero__eyebrow{display:inline-flex;gap:.45rem;align-items:center;margin-bottom:.55rem;font-size:.75rem;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:rgba(255,255,255,.78)}
    .asrama-hero h2{margin:0 0 .35rem;font-size:1.75rem;font-weight:750}.asrama-hero p{max-width:760px;margin:0;color:rgba(255,255,255,.9)}
    .asrama-panel{margin-bottom:1.35rem;border:0;border-radius:20px;background:#fff;box-shadow:0 12px 32px rgba(22,44,70,.08);overflow:hidden}
    .asrama-panel__header{display:flex;justify-content:space-between;align-items:center;gap:1rem;padding:1.15rem 1.35rem;border-bottom:1px solid #edf1f5}
    .asrama-panel__header h3{margin:0;font-size:1.05rem;font-weight:700;color:var(--asrama-ink)}.asrama-panel__header p{margin:.2rem 0 0;color:#718096;font-size:.86rem}
    .asrama-panel__body{padding:1.35rem}.asrama-stat{height:100%;padding:1.2rem;border-radius:18px;background:#fff;box-shadow:0 10px 26px rgba(22,44,70,.08);border-left:4px solid var(--asrama-teal)}
    .asrama-stat span{display:block;color:#718096;font-size:.78rem;text-transform:uppercase;letter-spacing:.04em}.asrama-stat strong{display:block;margin:.25rem 0;font-size:1.85rem;color:var(--asrama-navy)}.asrama-stat small{color:#8492a6}
    .asrama-table{margin:0}.asrama-table thead th{border-top:0;border-bottom:1px solid #dce5ed;background:#f7fafc;color:#516174;font-size:.75rem;text-transform:uppercase;letter-spacing:.035em;white-space:nowrap}
    .asrama-table td{vertical-align:middle}.asrama-arab{font-family:"Noto Naskh Arabic","Amiri","Traditional Arabic",serif;font-size:1.18em;direction:rtl}
    .asrama-badge{display:inline-flex;align-items:center;padding:.3rem .58rem;border-radius:999px;font-size:.75rem;font-weight:650}
    .asrama-badge--active{color:#08756f;background:#dff7f4}.asrama-badge--muted{color:#64748b;background:#eef2f6}
    .asrama-form label{font-weight:650;color:#435366;font-size:.86rem}.asrama-form .form-control{border-radius:10px;border-color:#dce4ec}.asrama-form .btn{border-radius:10px}
    .asrama-alert{border:0;border-radius:14px}.asrama-empty{padding:2.5rem;text-align:center;color:#718096}.asrama-empty i{display:block;margin-bottom:.75rem;font-size:2rem;color:#a8b6c5}
    @media(max-width:768px){.asrama-hero{align-items:flex-start;flex-direction:column}.asrama-hero__action{width:100%}.asrama-hero__action .btn{width:100%}.asrama-panel__header{align-items:flex-start;flex-direction:column}}
</style>
